const { useEffect, useId, useRef, useState } = React;

const Component = () => {
  const popoverId = useId();
  const triggerRef = useRef(null);
  const popoverRef = useRef(null);
  const [popoverOpen, setPopoverOpen] = useState(false);
  const [plainOpen, setPlainOpen] = useState(false);

  useEffect(() => {
    const trigger = triggerRef.current;
    const popover = popoverRef.current;
    // 声明式触发：按钮通过 popovertarget 引用浮层 id
    trigger.setAttribute("popovertarget", popoverId);
    const handleToggle = event => setPopoverOpen(event.newState === "open");
    popover.addEventListener("toggle", handleToggle);
    return () => {
      popover.removeEventListener("toggle", handleToggle);
      if (popover.matches?.(":popover-open")) popover.hidePopover();
    };
  }, [popoverId]);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          :scope { anchor-scope: all; }
          .cb-trigger { anchor-name: --cb-pop-basic; }
          .cb-pop {
            position-visibility: anchors-visible;
            position-anchor: --cb-pop-basic;
            inset: auto;
            margin: 8px 0 0;
            top: anchor(bottom);
            left: anchor(center);
            translate: -50% 0;
            position-try-fallbacks: flip-block;
          }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex min-w-0 flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <div className="flex flex-wrap gap-1.5">
            <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-tiny text-ink-2">overflow: hidden</code>
            <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-tiny text-ink-2">height: 96px</code>
          </div>
          {/* 受限容器：两种浮层都声明在它里面 */}
          <div className="relative grid h-24 grid-cols-2 items-start gap-3 overflow-hidden rounded-tau-sm border border-dashed border-line-1 bg-surface p-3">
            <div className="relative flex justify-center">
              <ui.Button variant="secondary" size="sm" onClick={() => setPlainOpen(value => !value)}>
                普通浮层
              </ui.Button>
              {plainOpen && (
                <div className="absolute left-1/2 top-full z-10 mt-2 w-[180px] -translate-x-1/2 rounded-tau-sm border border-line-1 bg-surface p-3 shadow-lift">
                  <span className="text-tau-meta text-ink-1">position: absolute 的浮层，下半截被容器裁掉了，这一行你可能看不到。</span>
                </div>
              )}
            </div>
            <div className="flex justify-center">
              <button
                ref={triggerRef}
                type="button"
                className="cb-trigger rounded-tau-sm bg-accent px-3 py-1.5 text-tau-body text-ink-inverse hover:bg-accent-hover"
              >
                popover 浮层
              </button>
            </div>
            <div
              id={popoverId}
              ref={popoverRef}
              popover="auto"
              className="cb-pop w-[200px] rounded-tau-sm border border-line-1 bg-surface p-3 text-ink-1 shadow-lift"
            >
              <span className="text-tau-meta text-ink-1">位于 top-layer，不被容器的 overflow 裁剪。点击外部或按 Esc 关闭。</span>
            </div>
          </div>
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">状态</span>
          <div className="flex items-center justify-between gap-2">
            <span className="text-tau-meta text-ink-2">普通浮层</span>
            <ui.Tag color={plainOpen ? "orange" : "gray"}>{plainOpen ? "显示，被裁剪" : "隐藏"}</ui.Tag>
          </div>
          <div className="flex items-center justify-between gap-2">
            <span className="font-tau-mono text-tau-meta text-ink-2">:popover-open</span>
            <ui.Tag color={popoverOpen ? "blue" : "gray"}>{String(popoverOpen)}</ui.Tag>
          </div>
          <pre className="m-0 mt-auto min-w-0 whitespace-pre-wrap break-all font-tau-mono text-tau-sm leading-[1.7] text-ink-3">
            {'<button popovertarget="pop">\n<div id="pop" popover>'}
          </pre>
        </div>
      </div>
    </div>
  );
};

const { useEffect, useId, useRef, useState } = React;

const GROUPS = [
  { type: "auto", how: "点击打开", color: "blue", note: "light dismiss，auto 之间互斥" },
  { type: "hint", how: "悬停打开", color: "purple", note: "light dismiss，不关已打开的 auto" },
  { type: "manual", how: "点击切换", color: "green", note: "不会自动关闭，可同时打开多个" },
];
const NAMES = ["A", "B"];
const POPOVERS = GROUPS.flatMap(group => NAMES.map(name => ({ ...group, name, key: `${group.type}-${name}` })));

const Component = () => {
  const baseId = useId();
  const triggerRefs = useRef({});
  const popoverRefs = useRef({});
  const [openKeys, setOpenKeys] = useState([]);
  const [log, setLog] = useState([]);
  const [hintSupported, setHintSupported] = useState(true);

  useEffect(() => {
    const popovers = { ...popoverRefs.current };
    const triggers = { ...triggerRefs.current };
    const handlers = POPOVERS.map(item => {
      const popover = popovers[item.key];
      if (item.type !== "hint") triggers[item.key].setAttribute("popovertarget", `${baseId}-${item.key}`);
      const handler = event => {
        const opened = event.newState === "open";
        setOpenKeys(keys => (opened ? [...keys.filter(key => key !== item.key), item.key] : keys.filter(key => key !== item.key)));
        setLog(list => [{ id: Date.now() + Math.random(), item, opened }, ...list].slice(0, 8));
      };
      popover.addEventListener("toggle", handler);
      return [popover, handler];
    });
    // 不支持 hint 的浏览器会把无效值当作 manual
    setHintSupported(popovers["hint-A"].popover === "hint");
    return () =>
      handlers.forEach(([popover, handler]) => {
        popover.removeEventListener("toggle", handler);
        if (popover.matches?.(":popover-open")) popover.hidePopover();
      });
  }, [baseId]);

  const showHint = key => {
    const popover = popoverRefs.current[key];
    if (!popover.matches?.(":popover-open")) popover.showPopover?.();
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          :scope { anchor-scope: all; }
          .cb-pop {
            position-visibility: anchors-visible;
            inset: auto;
            margin: 6px 0 0;
            top: anchor(bottom);
            left: anchor(center);
            translate: -50% 0;
          }
          .cb-row { animation: cb-pop-row 320ms var(--tau-ease-out) both; }
          @media (prefers-reduced-motion: reduce) {
            .cb-row { animation: none; }
          }
        }
        @keyframes cb-pop-row {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: none; }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex min-w-0 flex-col gap-2">
          {GROUPS.map(group => (
            <div key={group.type} className="flex flex-wrap items-start gap-3 rounded-tau-md border border-line-1 px-3 pb-10 pt-3">
              <div className="flex min-w-[140px] flex-1 flex-col gap-0.5">
                <div className="flex items-center gap-2">
                  <code className="font-tau-mono text-tau-meta text-ink-1">popover="{group.type}"</code>
                  {group.type === "hint" && !hintSupported && <ui.Tag color="orange">不支持，按 manual 处理</ui.Tag>}
                </div>
                <span className="text-tau-sm text-ink-3">{group.note}</span>
              </div>
              <div className="flex gap-2">
                {NAMES.map(name => {
                  const key = `${group.type}-${name}`;
                  return (
                    <button
                      key={key}
                      ref={node => {
                        triggerRefs.current[key] = node;
                      }}
                      type="button"
                      onPointerEnter={group.type === "hint" ? () => showHint(key) : undefined}
                      onFocus={group.type === "hint" ? () => showHint(key) : undefined}
                      style={{ anchorName: `--cb-types-${key}` }}
                      className={
                        openKeys.includes(key)
                          ? "w-16 rounded-tau-sm border border-accent bg-accent-soft py-1.5 text-tau-meta text-accent-text"
                          : "w-16 rounded-tau-sm border border-line-1 bg-surface py-1.5 text-tau-meta text-ink-1 hover:bg-hover"
                      }
                    >
                      {group.type === "hint" ? `悬停 ${name}` : name}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
          {POPOVERS.map(item => (
            <div
              key={item.key}
              id={`${baseId}-${item.key}`}
              ref={node => {
                popoverRefs.current[item.key] = node;
              }}
              popover={item.type}
              style={{ positionAnchor: `--cb-types-${item.key}` }}
              className="cb-pop rounded-tau-sm border border-line-1 bg-surface px-2 py-1 text-ink-1 shadow-lift"
            >
              <span className="whitespace-nowrap font-tau-mono text-tau-sm text-ink-1">
                {item.type} {item.name}
              </span>
            </div>
          ))}
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <div className="flex items-center justify-between gap-2">
            <span className="text-tau-sm text-ink-3">toggle 事件（新的在上）</span>
            {log.length > 0 && (
              <ui.Button variant="ghost" size="sm" onClick={() => setLog([])}>
                清空
              </ui.Button>
            )}
          </div>
          {log.length ? (
            <ol className="m-0 flex list-none flex-col gap-1.5 p-0">
              {log.map(entry => (
                <li key={entry.id} className="cb-row flex items-center gap-2">
                  <ui.Tag color={entry.item.color} className="shrink-0">
                    {entry.item.type}
                  </ui.Tag>
                  <span className="font-tau-mono text-tau-meta text-ink-1">{entry.item.name}</span>
                  <span className={entry.opened ? "ml-auto text-tau-sm text-ink-1" : "ml-auto text-tau-sm text-ink-3"}>
                    {entry.opened ? "打开" : "关闭"}
                  </span>
                </li>
              ))}
            </ol>
          ) : (
            <p className="m-0 text-tau-meta text-ink-3">先打开 auto A，再悬停 hint，再点 auto B</p>
          )}
          <span className="mt-auto font-tau-mono text-tau-sm text-ink-3">已打开：{openKeys.length ? openKeys.join("、") : "无"}</span>
        </div>
      </div>
    </div>
  );
};

const { useEffect, useId, useRef, useState } = React;

const ACTIONS = [
  { action: "toggle", label: "toggle", note: "打开与关闭之间切换" },
  { action: "show", label: "show", note: "始终打开，已打开则无变化" },
  { action: "hide", label: "hide", note: "始终关闭，已关闭则无变化" },
];

const Component = () => {
  const popoverId = useId();
  const popoverRef = useRef(null);
  const triggerRefs = useRef({});
  const timersRef = useRef(new Set());
  const [open, setOpen] = useState(false);
  const [lastAction, setLastAction] = useState(null);
  const [log, setLog] = useState([]);

  const isOpen = () => Boolean(popoverRef.current?.matches?.(":popover-open"));

  useEffect(() => {
    const popover = popoverRef.current;
    const timers = timersRef.current;
    ACTIONS.forEach(({ action }) => {
      const trigger = triggerRefs.current[action];
      trigger.setAttribute("popovertarget", popoverId);
      trigger.setAttribute("popovertargetaction", action);
    });
    const handleToggle = event => setOpen(event.newState === "open");
    popover.addEventListener("toggle", handleToggle);
    return () => {
      timers.forEach(clearTimeout);
      popover.removeEventListener("toggle", handleToggle);
      if (popover.matches?.(":popover-open")) popover.hidePopover();
    };
  }, [popoverId]);

  // 浏览器在 click 监听执行完后才执行 popovertarget 的默认动作，下一轮再读结果
  const handleClick = action => {
    const before = isOpen();
    setLastAction(action);
    const timer = setTimeout(() => {
      timersRef.current.delete(timer);
      const after = isOpen();
      setLog(list => [{ id: Date.now() + Math.random(), action, before, after }, ...list].slice(0, 6));
    }, 0);
    timersRef.current.add(timer);
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          :scope { anchor-scope: all; }
          .cb-anchor { anchor-name: --cb-action-anchor; }
          .cb-pop {
            position-visibility: anchors-visible;
            position-anchor: --cb-action-anchor;
            inset: auto;
            margin: 8px 0 0;
            top: anchor(bottom);
            left: anchor(center);
            translate: -50% 0;
            position-try-fallbacks: flip-block;
          }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3 pb-16">
          <pre className="m-0 min-w-0 overflow-x-auto font-tau-mono text-tau-sm leading-[1.7] text-ink-3">
            {ACTIONS.map(({ action }) => (
              <div key={action} className={lastAction === action ? "rounded-tau-sm bg-accent-soft text-accent-text" : ""}>
                {`<button popovertarget="pop" popovertargetaction="${action}">`}
              </div>
            ))}
          </pre>
          <div className="cb-anchor flex flex-wrap gap-2 self-start">
            {ACTIONS.map(({ action, label }) => (
              <button
                key={action}
                ref={node => {
                  triggerRefs.current[action] = node;
                }}
                type="button"
                onClick={() => handleClick(action)}
                className={
                  lastAction === action
                    ? "rounded-tau-sm border border-accent bg-accent-soft px-3 py-1.5 font-tau-mono text-tau-meta text-accent-text"
                    : "rounded-tau-sm border border-line-1 bg-surface px-3 py-1.5 font-tau-mono text-tau-meta text-ink-1 hover:bg-hover"
                }
              >
                {label}
              </button>
            ))}
          </div>
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <div className="flex items-center justify-between gap-2">
            <span className="font-tau-mono text-tau-meta text-ink-2">:popover-open</span>
            <ui.Tag color={open ? "blue" : "gray"}>{String(open)}</ui.Tag>
          </div>
          <span className="font-tau-mono text-tau-sm text-ink-3">最近点击：{lastAction ?? "无"}</span>
          <span className="text-tau-sm text-ink-3">点击结果（新的在上）</span>
          {log.length ? (
            <ol className="m-0 flex list-none flex-col gap-1.5 p-0">
              {log.map(entry => (
                <li key={entry.id} className="flex items-center gap-2">
                  <code className="w-14 shrink-0 font-tau-mono text-tau-sm text-ink-1">{entry.action}</code>
                  <span className="font-tau-mono text-tau-sm text-ink-3">{entry.before ? "open" : "closed"}</span>
                  <icons.ArrowRight className="size-3.5 shrink-0 text-ink-3" />
                  <span className="font-tau-mono text-tau-sm text-ink-1">{entry.after ? "open" : "closed"}</span>
                  {entry.before === entry.after && <span className="ml-auto text-tau-sm text-ink-3">无变化</span>}
                </li>
              ))}
            </ol>
          ) : (
            <p className="m-0 text-tau-meta text-ink-3">连续点 show 几次，再点 hide</p>
          )}
        </div>
      </div>
      <div
        id={popoverId}
        ref={popoverRef}
        popover="auto"
        className="cb-pop rounded-tau-sm border border-line-1 bg-surface px-3 py-2 text-ink-1 shadow-lift"
      >
        <span className="whitespace-nowrap text-tau-meta text-ink-1">同一个浮层，由三个按钮控制</span>
      </div>
    </div>
  );
};

