const { useEffect, useId, useRef, useState } = React;

const WINDOW_MS = 500;
const DURATION_MS = 200;
const CHART = { width: 240, height: 64, pad: 4 };

const buildStyle = (starting, discrete) => `
  @scope {
    :scope { anchor-scope: all; }
    .cb-trigger { anchor-name: --cb-anim-trigger; }
    .cb-pop {
      position-visibility: anchors-visible;
      position-anchor: --cb-anim-trigger;
      inset: auto;
      margin: 8px 0 0;
      top: anchor(bottom);
      left: anchor(center);
      translate: -50% 0;
      opacity: 0;
      transform: scale(0.95);
      transition: opacity ${DURATION_MS}ms, transform ${DURATION_MS}ms${
        discrete ? `, display ${DURATION_MS}ms allow-discrete, overlay ${DURATION_MS}ms allow-discrete` : ""
      };
    }
    .cb-pop:popover-open {
      opacity: 1;
      transform: scale(1);
      ${starting ? "@starting-style { opacity: 0; transform: scale(0.95); }" : ""}
    }
  }
`;

const codeLines = discrete => [
  { text: "[popover] {" },
  { text: "  opacity: 0;" },
  { text: "  transform: scale(0.95);" },
  { text: "  transition: opacity 0.2s, transform 0.2s" + (discrete ? "," : ";") },
  { text: "              display 0.2s allow-discrete,", flag: "discrete" },
  { text: "              overlay 0.2s allow-discrete;", flag: "discrete" },
  { text: "}" },
  { text: "[popover]:popover-open { opacity: 1; transform: scale(1); }" },
  { text: "@starting-style {", flag: "starting" },
  { text: "  [popover]:popover-open { opacity: 0; transform: scale(0.95); }", flag: "starting" },
  { text: "}", flag: "starting" },
];

// 逐帧采样浮层的可见程度：display 为 none 时记为 0
const useOpacityTrace = ref => {
  const frameRef = useRef(0);
  const [samples, setSamples] = useState([]);
  useEffect(() => () => cancelAnimationFrame(frameRef.current), []);
  const record = () => {
    cancelAnimationFrame(frameRef.current);
    const points = [];
    let start = 0;
    const tick = now => {
      start ||= now;
      const style = getComputedStyle(ref.current);
      points.push([now - start, style.display === "none" ? 0 : Number(style.opacity)]);
      setSamples([...points]);
      if (now - start < WINDOW_MS) frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
  };
  return [samples, record];
};

const OpacityChart = ({ samples }) => {
  const toX = time => (Math.min(time, WINDOW_MS) / WINDOW_MS) * CHART.width;
  const toY = value => CHART.height - CHART.pad - value * (CHART.height - CHART.pad * 2);
  const line = samples.map(([time, value]) => `${toX(time)},${toY(value)}`).join(" ");
  const current = samples.length ? samples[samples.length - 1][1] : 0;
  return (
    <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
      <div className="flex items-baseline justify-between">
        <span className="text-tau-sm text-ink-3">opacity 变化</span>
        <span className="font-tau-mono text-tau-sm text-ink-2">{current.toFixed(2)}</span>
      </div>
      <svg viewBox={`0 0 ${CHART.width} ${CHART.height}`} preserveAspectRatio="none" className="h-16 w-full overflow-visible">
        <line
          x1="0"
          x2={CHART.width}
          y1={toY(1)}
          y2={toY(1)}
          className="stroke-line-1"
          strokeDasharray="3 3"
          vectorEffect="non-scaling-stroke"
        />
        <line x1="0" x2={CHART.width} y1={toY(0)} y2={toY(0)} className="stroke-line-1" vectorEffect="non-scaling-stroke" />
        <line
          x1={toX(DURATION_MS)}
          x2={toX(DURATION_MS)}
          y1="0"
          y2={CHART.height}
          className="stroke-line-2"
          strokeDasharray="2 3"
          vectorEffect="non-scaling-stroke"
        />
        {line && (
          <polyline
            points={line}
            className="fill-none stroke-accent"
            strokeWidth="2"
            strokeLinejoin="round"
            vectorEffect="non-scaling-stroke"
          />
        )}
      </svg>
      <div className="flex justify-between font-tau-mono text-tau-tiny text-ink-3">
        <span>0ms</span>
        <span>transition {DURATION_MS}ms</span>
      </div>
    </div>
  );
};

const Component = () => {
  const popoverId = useId();
  const triggerRef = useRef(null);
  const popoverRef = useRef(null);
  const [open, setOpen] = useState(false);
  const [starting, setStarting] = useState(true);
  const [discrete, setDiscrete] = useState(true);
  const [samples, record] = useOpacityTrace(popoverRef);
  const recordRef = useRef(record);
  recordRef.current = record;

  useEffect(() => {
    const popover = popoverRef.current;
    triggerRef.current.setAttribute("popovertarget", popoverId);
    // beforetoggle 在状态切换前同步触发，从这里开始采样能拿到第一帧
    const handleBeforeToggle = () => recordRef.current();
    const handleToggle = event => setOpen(event.newState === "open");
    popover.addEventListener("beforetoggle", handleBeforeToggle);
    popover.addEventListener("toggle", handleToggle);
    return () => {
      popover.removeEventListener("beforetoggle", handleBeforeToggle);
      popover.removeEventListener("toggle", handleToggle);
      if (popover.matches?.(":popover-open")) popover.hidePopover();
    };
  }, [popoverId]);

  const flags = { starting, discrete };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{buildStyle(starting, discrete)}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex h-[160px] min-w-0 items-start justify-center rounded-tau-md border border-line-1 p-4">
          <button
            ref={triggerRef}
            type="button"
            className="cb-trigger rounded-tau-sm bg-accent px-3 py-1.5 text-tau-body text-ink-inverse hover:bg-accent-hover"
          >
            {open ? "关闭浮层" : "打开浮层"}
          </button>
          <div
            id={popoverId}
            ref={popoverRef}
            popover="auto"
            className="cb-pop w-[220px] rounded-tau-sm border border-line-1 bg-surface p-3 text-ink-1 shadow-lift"
          >
            <div className="flex flex-col gap-1">
              <span className="text-tau-body text-ink-1">{starting ? "入场从 @starting-style 起步" : "入场没有起点，直接出现"}</span>
              <span className="text-tau-sm text-ink-3">{discrete ? "退场播完才 display: none" : "退场瞬间 display: none"}</span>
            </div>
          </div>
        </div>
        <OpacityChart samples={samples} />
      </div>
      <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
        {codeLines(discrete).map((line, index) => (
          <div
            key={index}
            className={!line.flag ? "" : flags[line.flag] ? "rounded-tau-sm bg-accent-soft text-accent-text" : "text-ink-3 line-through"}
          >
            {line.text}
          </div>
        ))}
      </pre>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.Switch checked={starting} onCheckedChange={setStarting} label="@starting-style" size="sm" />
        <ui.Switch checked={discrete} onCheckedChange={setDiscrete} label="allow-discrete" size="sm" />
      </div>
    </div>
  );
};

