content.content:
const { useEffect, useId, useRef, useState } = React;

const PLACEMENTS = {
  bottom: { label: "下方", rules: ["top: anchor(bottom);", "left: anchor(center);", "translate: -50% 0;", "margin-top: 10px;"] },
  top: { label: "上方", rules: ["bottom: anchor(top);", "left: anchor(center);", "translate: -50% 0;", "margin-bottom: 10px;"] },
  right: { label: "右侧", rules: ["left: anchor(right);", "top: anchor(center);", "translate: 0 -50%;", "margin-left: 10px;"] },
  left: { label: "左侧", rules: ["right: anchor(left);", "top: anchor(center);", "translate: 0 -50%;", "margin-right: 10px;"] },
};

const buildStyle = (placement, blockPage) => `
  @scope {
    :scope { anchor-scope: all; }
    .cb-trigger { anchor-name: --cb-anchor-trigger; }
    .cb-pop {
      position-anchor: --cb-anchor-trigger;
      position-visibility: anchors-visible;
      inset: auto;
      margin: 0;
      ${PLACEMENTS[placement].rules.join("\n      ")}
    }
    ${blockPage ? ".cb-pop::backdrop { pointer-events: auto; background: var(--tau-overlay); }" : ""}
  }
`;

const readBackdrop = popover => {
  try {
    return getComputedStyle(popover, "::backdrop").pointerEvents || "未知";
  } catch {
    return "未知";
  }
};

const Component = () => {
  const popoverId = useId();
  const triggerRef = useRef(null);
  const popoverRef = useRef(null);
  const [placement, setPlacement] = useState("bottom");
  const [blockPage, setBlockPage] = useState(false);
  const [open, setOpen] = useState(false);
  const [clicks, setClicks] = useState(0);
  const [backdrop, setBackdrop] = useState(null);

  useEffect(() => {
    const popover = popoverRef.current;
    triggerRef.current.setAttribute("popovertarget", popoverId);
    const handleToggle = event => setOpen(event.newState === "open");
    // 点在 ::backdrop 上时事件目标是浮层本身，用矩形判断点在了外面就关闭
    const handleClick = event => {
      if (event.target !== popover) return;
      const rect = popover.getBoundingClientRect();
      const outside = event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom;
      if (outside) popover.hidePopover();
    };
    popover.addEventListener("toggle", handleToggle);
    popover.addEventListener("click", handleClick);
    return () => {
      popover.removeEventListener("toggle", handleToggle);
      popover.removeEventListener("click", handleClick);
      if (popover.matches?.(":popover-open")) popover.hidePopover();
    };
  }, [popoverId]);

  // 样式更新后再读 ::backdrop 的计算值
  useEffect(() => {
    if (open) setBackdrop(readBackdrop(popoverRef.current));
  }, [open, blockPage]);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{buildStyle(placement, blockPage)}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative grid h-[220px] min-w-0 place-items-center rounded-tau-md border border-line-1 p-3">
          <ui.Button variant="soft" size="sm" className="absolute left-3 top-3" onClick={() => setClicks(count => count + 1)}>
            页面按钮 · {clicks}
          </ui.Button>
          <button
            ref={triggerRef}
            type="button"
            className="cb-trigger rounded-tau-sm bg-accent px-4 py-2 text-tau-body text-ink-inverse hover:bg-accent-hover"
          >
            {open ? "收起浮层" : "触发元素"}
          </button>
          <div
            id={popoverId}
            ref={popoverRef}
            popover="manual"
            className="cb-pop rounded-tau-sm border border-line-1 bg-surface px-3 py-2 text-ink-1 shadow-lift"
          >
            <span className="whitespace-nowrap text-tau-meta text-ink-1">定位到触发元素{PLACEMENTS[placement].label}</span>
          </div>
        </div>
        <div className="flex min-w-0 flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">当前定位规则</span>
          <pre className="m-0 min-w-0 whitespace-pre-wrap break-all rounded-tau-sm bg-hover px-2.5 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
            {["position-anchor: --trigger;", ...PLACEMENTS[placement].rules].join("\n")}
          </pre>
          <div className="mt-auto flex flex-col gap-1 font-tau-mono text-tau-sm text-ink-3">
            <span>::backdrop pointer-events：{open ? (backdrop ?? "未知") : "浮层未打开"}</span>
            <span>{blockPage ? "已声明 pointer-events: auto" : "未覆盖，使用默认值"}</span>
          </div>
        </div>
      </div>
      <div className="flex flex-wrap items-end gap-x-6 gap-y-3">
        <ui.RadioGroup label="定位方向" value={placement} onValueChange={setPlacement} orientation="horizontal">
          {Object.entries(PLACEMENTS).map(([value, item]) => (
            <ui.Radio key={value} value={value} label={item.label} />
          ))}
        </ui.RadioGroup>
        <ui.Switch checked={blockPage} onCheckedChange={setBlockPage} label="::backdrop 拦截交互" size="sm" />
      </div>
    </div>
  );
};
